CREATE OR REPLACE FUNCTION public.get_team_game_questions(_users uuid[]) RETURNS SETOF public.chem_questions LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_staff(auth.uid()) OR cardinality(_users)=0 OR cardinality(_users)>100 THEN RAISE EXCEPTION 'Equipe inválida ou acesso negado'; END IF; RETURN QUERY SELECT q.* FROM public.chem_questions q WHERE NOT EXISTS(SELECT 1 FROM unnest(_users) uid WHERE NOT public.game_question_eligible(uid,q.id) OR EXISTS(SELECT 1 FROM public.student_question_history h WHERE h.user_id=uid AND (h.question_id=q.id OR lower(btrim(h.question_text))=lower(btrim(q.question)))) OR EXISTS(SELECT 1 FROM public.game_question_log l WHERE l.user_id=uid AND lower(btrim(l.question))=lower(btrim(q.question)))) ORDER BY q.id; END $$;
REVOKE ALL ON FUNCTION public.get_team_game_questions(uuid[]) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.get_team_game_questions(uuid[]) TO authenticated;
CREATE OR REPLACE FUNCTION public.reserve_team_question(_team uuid,_question uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; q public.chem_questions; BEGIN IF NOT public.is_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF; SELECT * INTO q FROM public.chem_questions WHERE id=_question; IF q.id IS NULL THEN RETURN false; END IF; FOR uid IN SELECT user_id FROM public.class_team_members WHERE team_id=_team ORDER BY user_id LOOP PERFORM pg_advisory_xact_lock(hashtextextended(uid::text,0)); IF NOT public.game_question_eligible(uid,_question) OR EXISTS(SELECT 1 FROM public.student_question_history h WHERE h.user_id=uid AND (h.question_id=q.id OR lower(btrim(h.question_text))=lower(btrim(q.question)))) OR EXISTS(SELECT 1 FROM public.game_question_log l WHERE l.user_id=uid AND lower(btrim(l.question))=lower(btrim(q.question))) THEN RETURN false; END IF; END LOOP; INSERT INTO public.student_question_history(user_id,question_id,question_text,game) SELECT user_id,q.id,q.question,'Sala de Equipes' FROM public.class_team_members WHERE team_id=_team ON CONFLICT DO NOTHING; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.reserve_team_question(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.reserve_team_question(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.answer_team_question(_team uuid,_question uuid,_answer text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.chem_questions; ok boolean; correct text; uid uuid; BEGIN IF NOT public.is_staff(auth.uid()) OR length(_answer)>4000 THEN RAISE EXCEPTION 'Acesso negado'; END IF; SELECT * INTO q FROM public.chem_questions WHERE id=_question; correct:=coalesce(q.options->>q.correct_index,q.answer_text,''); ok:=lower(btrim(_answer))=lower(btrim(correct)); FOR uid IN SELECT user_id FROM public.class_team_members WHERE team_id=_team LOOP UPDATE public.student_question_history SET answered_at=now(),answer=_answer,correct_answer=correct,is_correct=ok,points=CASE WHEN ok THEN 4 ELSE 1 END WHERE user_id=uid AND question_id=_question AND answered_at IS NULL; IF FOUND THEN INSERT INTO public.game_question_log(user_id,game,question,answer,correct_answer,is_correct) VALUES(uid,'Sala de Equipes',q.question,_answer,correct,ok); END IF; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.answer_team_question(uuid,uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.answer_team_question(uuid,uuid,text) TO authenticated;